floor_fn:
"""How are we going to call the underlying implementation of a
    declaration?  There are two strategies:

        - use_derived: we want to call the implementation on CPUDoubleType
          (or a similar, derived Type instance).  Because these derived
          instances deal in Tensors, not Variables (it's a completely different
          object, so it doesn't dispatch back to VariableType), code on
          this dispatch path needs to wrap/unwrap tensors.  If the
          derived implementation takes and returns tensors, the
          implementation is usually differentiable (although we also use
          the derived dispatch path for non-differentiable functions
          that we still want to dispatch on the derived Type instance;
          e.g., size())

        - use_type: we want to call the implementation on Type, because
          it is implemented concretely, and the functions it invokes will
          get dispatched back to VariableType (which will ensure that they
          are differentiable.)
    """
def dispatch_strategy(declaration: Any) -> object {
    if (declaration['abstract'] or (declaration['derivative'] is not None)) {
        return 'use_derived';
    } else {
        return 'use_type';
    }
}

test_blocks:
test "t0" {
    assert (
        dispatch_strategy(
            {"abstract": True, "derivative": None, "name": "foo", "return_type": "int"}
        )
        == 'use_derived'
    );;
}

test "t1" {
    assert (
        dispatch_strategy(
            {
                "name": "foo",
                "overload_name": "foo",
                "schema_string": "foo(Tensor self) -> Tensor",
                "dispatch": "use_type",
                "default": [],
                "abstract": False,
                "derivative": None,
                "inplace": False,
                "python_module": False,
                "returns_void": False,
                "return_type": {"type": "Tensor", "argument": "self"},
                "arguments": [{"type": "Tensor", "argument": "self", "default": None}]
            }
        )
        == 'use_type'
    );;
}

test "t2" {
    assert (
        dispatch_strategy(
            {
                'derivative': None,
                'abstract': True,
                'method_of': ['Tensor'],
                'python_module': 'Tensor'
            }
        )
        == 'use_derived'
    );;
}

test "t3" {
    assert (
        dispatch_strategy(
            {"schema_string": "my_test_function(Tensor t) -> Tensor", "abstract": True}
        )
        == 'use_derived'
    );;
}

